package com.javacodingagent.core;
import com.javacodingagent.common.domain.AgentExecutionContext; import com.javacodingagent.tools.ToolResult; import com.javacodingagent.trace.*; import java.time.Instant; import java.util.Map; import java.util.concurrent.atomic.AtomicLong; import java.util.function.Supplier;
/** Central tool decorator; individual tools contain no trace persistence code. */
public class TraceableToolExecutor { private final TraceStore traces; private final AtomicLong sequence = new AtomicLong(); public TraceableToolExecutor(TraceStore traces) { this.traces = traces; } public <T> ToolResult<T> execute(AgentExecutionContext context, String inputSummary, Supplier<ToolResult<T>> call) { ToolResult<T> result = call.get(); try { traces.append(new TraceEvent(context.getTraceId(), context.getTaskId(), sequence.incrementAndGet(), "TOOL_" + (result.success() ? "FINISHED" : "FAILED"), "TOOL_EXECUTOR", result.toolName() + ": " + result.summary(), Map.of("input", redact(inputSummary), "durationMs", String.valueOf(result.durationMs())), Instant.now())); } catch (RuntimeException ignored) { } return result; } private String redact(String value) { return value == null ? "" : value.replaceAll("(?i)(api[-_ ]?key|token|password|secret|authorization)\\s*[:=]\\s*\\S+", "$1=[REDACTED]"); } }
